function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 30) return 'Each word has 1 to 30 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase English letters only.';
  }
  if (new Set(words).size !== words.length) return 'All words must be different.';
  return null;
}

