function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, large ? int(2, 26) : int(1, 3));
  const count = large ? 100 : int(1, 7);
  const maxLength = large ? 30 : 5;
  const randomWord = () => {
    const length = int(1, maxLength);
    let word = '';
    for (let k = 0; k < length; k++) word += letters[Math.floor(rand() * letters.length)];
    return word;
  };
  const seen = new Set();
  const words = [];
  let attempts = 0;
  while (words.length < count && attempts < 5000) {
    attempts++;
    let word;
    if (words.length > 0 && rand() < 0.4) {
      // Cut a piece out of an earlier word so substring matches are common.
      const source = words[Math.floor(rand() * words.length)];
      const start = int(0, source.length - 1);
      word = source.slice(start, int(start + 1, source.length));
    } else {
      word = randomWord();
    }
    if (seen.has(word)) continue;
    seen.add(word);
    words.push(word);
  }
  // Shuffle so short pieces are not always after the words they came from.
  for (let k = words.length - 1; k > 0; k--) {
    const r = Math.floor(rand() * (k + 1));
    [words[k], words[r]] = [words[r], words[k]];
  }
  return [words];
}
